namespace fuse::renderer::frame {

namespace {
constexpr u32 kPushBytes = sizeof(FramePush);
constexpr u32 kFrameStride = 256u; ///< ring slot size (>= sizeof(FrameConstants), 256-aligned)
static_assert(sizeof(FrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kViewStride = 256u;  ///< RtfxShadowView ring slot
constexpr u32 kColorFormat = static_cast<u32>(GpuFormat::R16G16B16A16Sfloat);
constexpr u32 kJitterPhases = 8u;

BufferUsage bufferUsage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

ImageUsage imageUsage(std::initializer_list<ImageUsage> bits) {
    u32 u = 0;
    for (const ImageUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<ImageUsage>(u);
}

u32 groups(u32 items) { return items == 0u ? 1u : (items + kFrameTile - 1u) / kFrameTile; }

// --- camera math (column-major, Vulkan clip space with NDC y down, forward depth) -----------------------------
void mul4(const f32 a[16], const f32 b[16], f32 out[16]) {
    for (u32 c = 0; c < 4u; ++c) {
        for (u32 r = 0; r < 4u; ++r) {
            f64 s = 0.0;
            for (u32 k = 0; k < 4u; ++k) {
                s += static_cast<f64>(a[k * 4u + r]) * b[c * 4u + k];
            }
            out[c * 4u + r] = static_cast<f32>(s);
        }
    }
}

void perspective(f32 fovY, f32 aspect, f32 zNear, f32 zFar, bool flipY, f32 out[16]) {
    const f32 f = 1.f / std::tan(fovY * 0.5f);
    std::memset(out, 0, 16u * sizeof(f32));
    out[0] = f / aspect;
    out[5] = flipY ? -f : f;
    out[10] = zFar / (zNear - zFar);
    out[11] = -1.f;
    out[14] = zNear * zFar / (zNear - zFar);
}

struct Basis {
    f32 f[3];
    f32 s[3];
    f32 u[3];
};

Basis basisOf(const f32 eye[3], const f32 at[3]) {
    Basis b{};
    f32 f[3] = {at[0] - eye[0], at[1] - eye[1], at[2] - eye[2]};
    const f32 fl = std::sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);
    for (f32& v : f) {
        v /= fl > 0.f ? fl : 1.f;
    }
    const f32 up[3] = {0.f, std::fabs(f[1]) > 0.999f ? 0.f : 1.f, std::fabs(f[1]) > 0.999f ? 1.f : 0.f};
    f32 s[3] = {f[1] * up[2] - f[2] * up[1], f[2] * up[0] - f[0] * up[2], f[0] * up[1] - f[1] * up[0]};
    const f32 sl = std::sqrt(s[0] * s[0] + s[1] * s[1] + s[2] * s[2]);
    for (f32& v : s) {
        v /= sl;
    }
    const f32 u[3] = {s[1] * f[2] - s[2] * f[1], s[2] * f[0] - s[0] * f[2], s[0] * f[1] - s[1] * f[0]};
    std::memcpy(b.f, f, sizeof(f));
    std::memcpy(b.s, s, sizeof(s));
    std::memcpy(b.u, u, sizeof(u));
    return b;
}

void lookAt(const f32 eye[3], const Basis& b, f32 v[16]) {
    std::memset(v, 0, 16u * sizeof(f32));
    v[0] = b.s[0];
    v[4] = b.s[1];
    v[8] = b.s[2];
    v[1] = b.u[0];
    v[5] = b.u[1];
    v[9] = b.u[2];
    v[2] = -b.f[0];
    v[6] = -b.f[1];
    v[10] = -b.f[2];
    v[12] = -(b.s[0] * eye[0] + b.s[1] * eye[1] + b.s[2] * eye[2]);
    v[13] = -(b.u[0] * eye[0] + b.u[1] * eye[1] + b.u[2] * eye[2]);
    v[14] = b.f[0] * eye[0] + b.f[1] * eye[1] + b.f[2] * eye[2];
    v[15] = 1.f;
}

/// Gauss-Jordan inverse in f64 (column-major), rounded to f32.
bool invert(const f32 in[16], f32 out[16]) {
    f64 a[4][8];
    for (u32 r = 0; r < 4u; ++r) {
        for (u32 c = 0; c < 4u; ++c) {
            a[r][c] = in[c * 4u + r];
            a[r][c + 4u] = r == c ? 1.0 : 0.0;
        }
    }
    for (u32 c = 0; c < 4u; ++c) {
        u32 piv = c;
        for (u32 r = c + 1u; r < 4u; ++r) {
            if (std::fabs(a[r][c]) > std::fabs(a[piv][c])) {
                piv = r;
            }
        }
        if (std::fabs(a[piv][c]) < 1e-30) {
            return false;
        }
        for (u32 k = 0; k < 8u; ++k) {
            std::swap(a[c][k], a[piv][k]);
        }
        const f64 d = a[c][c];
        for (u32 k = 0; k < 8u; ++k) {
            a[c][k] /= d;
        }
        for (u32 r = 0; r < 4u; ++r) {
            if (r != c) {
                const f64 m = a[r][c];
                for (u32 k = 0; k < 8u; ++k) {
                    a[r][k] -= m * a[c][k];
                }
            }
        }
    }
    for (u32 r = 0; r < 4u; ++r) {
        for (u32 c = 0; c < 4u; ++c) {
            out[c * 4u + r] = static_cast<f32>(a[r][c + 4u]);
        }
    }
    return true;
}

math::Mat4 toMath(const f32 m[16]) {
    math::Mat4 r{};
    for (u32 i = 0; i < 16u; ++i) {
        r.data[i] = m[i];
    }
    return r;
}

math::Vec3 vec3(const f32 v[3]) { return math::Vec3{v[0], v[1], v[2]}; }

math::Vec3 normalized(const f32 v[3]) {
    const f32 l = std::sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
    return l > 0.f ? math::Vec3{v[0] / l, v[1] / l, v[2] / l} : math::Vec3{0.f, 1.f, 0.f};
}

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

FrameComposer::~FrameComposer() { destroy(); }

bool FrameComposer::init(const FrameComposerDesc& desc) {
    destroy();
    m_desc = desc;
    if (m_desc.displayWidth == 0u || m_desc.displayHeight == 0u) {
        m_desc.displayWidth = m_desc.renderWidth;
        m_desc.displayHeight = m_desc.renderHeight;
    }
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.scene == nullptr ||
        desc.renderWidth == 0u || desc.renderHeight == 0u || m_desc.displayWidth < desc.renderWidth ||
        m_desc.displayHeight < desc.renderHeight || desc.framesInFlight == 0u) {
        m_reason = "invalid description";
        return false;
    }
    if (desc.tier == FrameTier::T2 && !rt::queryRtCapabilities(desc.device).usable) {
        m_reason = "T2 requested below the T2 gate (rt::queryRtCapabilities)";
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    const u32 w = desc.renderWidth;
    const u32 h = desc.renderHeight;
    auto fail = [&](const char* why) {
        m_reason = why;
        destroy();
        m_reason = why;
        return false;
    };

    // --- mandatory: scene path + lighting ---------------------------------------------------------------
    culling::InstanceCullerDesc cd{};
    cd.device = desc.device;
    cd.allocator = desc.allocator;
    cd.bindless = desc.bindless;
    cd.instanceCapacity = desc.instanceCapacity;
    cd.framesInFlight = desc.framesInFlight;
    if (!m_culler.init(cd) || !m_culler.setResolution(w, h)) {
        return fail("instance culler");
    }
    visbuffer::VisBufferDesc vd{};
    vd.device = desc.device;
    vd.allocator = desc.allocator;
    vd.bindless = desc.bindless;
    vd.width = w;
    vd.height = h;
    vd.mode = visbuffer::VisMode::Raster;
    if (!m_vb.init(vd)) {
        return fail("visibility buffer");
    }
    material_resolve::MaterialResolveDesc md{};
    md.device = desc.device;
    md.allocator = desc.allocator;
    md.bindless = desc.bindless;
    md.width = w;
    md.height = h;
    md.framesInFlight = desc.framesInFlight;
    if (!m_resolve.init(md)) {
        return fail("material resolve");
    }
    temporal::TemporalMotionDesc tmd{};
    tmd.device = desc.device;
    tmd.allocator = desc.allocator;
    tmd.bindless = desc.bindless;
    tmd.width = w;
    tmd.height = h;
    tmd.framesInFlight = desc.framesInFlight;
    if (!m_motion.init(tmd)) {
        return fail("motion vectors");
    }
    lighting_gpu::ClusteredLightingDesc ld{};
    ld.device = desc.device;
    ld.allocator = desc.allocator;
    ld.bindless = desc.bindless;
    ld.clusters = desc.clusters;
    ld.lightCapacity = desc.lightCapacity;
    ld.width = w;
    ld.height = h;
    ld.framesInFlight = desc.framesInFlight;
    if (!m_lighting.init(ld)) {
        return fail("clustered lighting");
    }
    m_available = kStageScene | kStageLighting | kStageResolve;
    m_reason = "ok";
    auto optional = [&](bool ok, u32 stage, const char* why) {
        if (ok) {
            m_available |= stage;
        } else if (std::strcmp(m_reason, "ok") == 0) {
            m_reason = why;
        }
    };

    // --- optional stages ------------------------------------------------------------------------------------
    {
        vsm::VirtualShadowMapDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.clipmap = desc.vsmClipmap;
        d.poolPagesX = desc.vsmPoolPagesX;
        d.poolPagesY = desc.vsmPoolPagesY;
        d.instanceCapacity = desc.instanceCapacity;
        d.framesInFlight = desc.framesInFlight;
        vsm::VsmShadowsDesc sd{};
        sd.device = desc.device;
        sd.allocator = desc.allocator;
        sd.bindless = desc.bindless;
        sd.localPagesX = desc.vsmLocalPagesX;
        sd.localPagesY = desc.vsmLocalPagesY;
        sd.framesInFlight = desc.framesInFlight;
        optional(m_vsm.init(d) && m_vsmShadows.init(sd), kStageVsm, "virtual shadow map");
    }
    if (desc.tier == FrameTier::T2) {
        rt::AccelerationStructuresDesc ad{};
        ad.device = desc.device;
        ad.allocator = desc.allocator;
        ad.upload = desc.upload;
        ad.scene = desc.scene;
        ad.bindless = desc.bindless;
        ad.instanceCapacity = desc.instanceCapacity;
        ad.meshCapacity = desc.meshCapacity;
        if (!m_as.init(ad)) {
            return fail("acceleration structures (T2)");
        }
        m_available |= kStageTlas;
        rt_effects::RtEffectsDesc fd{};
        fd.device = desc.device;
        fd.allocator = desc.allocator;
        fd.bindless = desc.bindless;
        fd.width = w;
        fd.height = h;
        fd.framesInFlight = desc.framesInFlight;
        optional(m_rtfx.init(fd), kStageRtShadows, "rt effects");
        denoise::SvgfDenoiserDesc dd{};
        dd.device = desc.device;
        dd.allocator = desc.allocator;
        dd.bindless = desc.bindless;
        dd.framesInFlight = desc.framesInFlight;
        optional(m_svgf.init(dd), kStageDenoise, "denoiser");
    }
    {
        gi_gpu::DdgiGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.volume = desc.ddgiVolume;
        d.config = desc.ddgiConfig;
        d.tracer = desc.tier == FrameTier::T2 ? gi_gpu::DdgiTracer::RayQuery : gi_gpu::DdgiTracer::Sdf;
        d.framesInFlight = desc.framesInFlight;
        d.sdfCapacity = desc.ddgiSdfCapacity;
        d.surfaceCapacity = desc.ddgiSdfCapacity;
        optional(m_ddgi.init(d), kStageDdgi, "ddgi");
    }
    {
        ssfx_gpu::SsfxGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        optional(m_ssfx.init(d), kStageSsfx, "ssfx");
    }
    {
        atmosphere::AtmosphereGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        optional(m_atmosphere.init(d), kStageAtmosphere | kStageSky, "atmosphere");
    }
    {
        volumetric_gpu::FroxelFogDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        optional(m_fog.init(d), kStageFog, "froxel fog");
    }
    {
        clouds::CloudGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        optional(m_clouds.init(d), kStageClouds, "clouds");
    }
    {
        gsplat::GsplatDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        d.maxSplats = desc.maxSplats;
        d.maxEntries = desc.maxSplatEntries;
        optional(m_gsplat.init(d), kStageSplats, "gaussian splats");
    }
    UpscaleResolution res{};
    res.render_width = w;
    res.render_height = h;
    res.display_width = m_desc.displayWidth;
    res.display_height = m_desc.displayHeight;
    {
        temporal::TaauGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.resolution = res;
        d.settings = desc.taau;
        d.framesInFlight = desc.framesInFlight;
        optional(m_taau.init(d), kStageTaau, "taau");
    }
    {
        fsr3::Fsr3GpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.maxResolution = res;
        d.settings = desc.fsr3;
        d.framesInFlight = desc.framesInFlight;
        optional(m_fsr3.init(d), kStageFsr3, "fsr3");
    }
    {
        post_gpu::PostStackGpuDesc d{};
        d.device = desc.device;
        d.allocator = desc.allocator;
        d.bindless = desc.bindless;
        d.framesInFlight = desc.framesInFlight;
        optional(m_post.init(d), kStagePost, "post stack");
    }

    // --- composer-owned resources --------------------------------------------------------------------------
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride * 2u;
    ring.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "frame.constants";
    if (!desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr || m_frameRing.deviceAddress == 0u) {
        return fail("frame constant ring");
    }
    ring.size = static_cast<usize>(desc.framesInFlight) * kViewStride;
    ring.name = "frame.shadow_view";
    if (!desc.allocator->createBuffer(ring, m_viewRing) || m_viewRing.mapped == nullptr || m_viewRing.deviceAddress == 0u) {
        return fail("shadow view ring");
    }
    SamplerDesc trilinear{};
    trilinear.minFilter = VK_FILTER_LINEAR;
    trilinear.magFilter = VK_FILTER_LINEAR;
    trilinear.addressMode = VK_SAMPLER_ADDRESS_MODE_REPEAT;
    trilinear.name = "frame.material_sampler";
    m_sampler = desc.bindless->acquireSampler(trilinear);
    if (!m_sampler.isValid()) {
        return fail("material sampler");
    }
    m_samplerHandle = desc.bindless->shaderHandle(m_sampler);
    if (!createPipeline()) {
        return fail("frame kernel not built / pipeline");
    }
    if (!createTargets()) {
        return fail("frame targets");
    }
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void FrameComposer::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    m_post.destroy();
    m_fsr3.destroy();
    m_taau.destroy();
    m_gsplat.destroy();
    m_clouds.destroy();
    m_fog.destroy();
    m_atmosphere.destroy();
    m_ssfx.destroy();
    m_lighting.destroy();
    m_ddgi.destroy();
    m_svgf.destroy();
    m_rtfx.destroy();
    m_as.destroy();
    m_vsmShadows.destroy();
    m_vsm.destroy();
    m_motion.destroy();
    m_resolve.destroy();
    m_vb.destroy();
    m_culler.destroy();
    destroyTargets();
    for (u32 i = 0; i < m_sampledCount; ++i) {
        if (m_sampled[i].slot.isValid()) {
            m_desc.bindless->unregisterSlot(m_sampled[i].slot);
        }
        m_sampled[i] = SampledSlot{};
    }
    m_sampledCount = 0;
    if (m_sampler.isValid()) {
        m_desc.bindless->releaseSampler(m_sampler);
    }
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    if (m_viewRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_viewRing);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_sampler = BindlessSlotHandle{};
    m_samplerHandle = 0;
    m_frameRing = Buffer{};
    m_viewRing = Buffer{};
    m_frameAddress = m_viewAddress = 0;
    m_recordCount = 0;
    m_available = 0;
    m_plan = 0;
    m_begun = false;
    m_hasPrev = false;
    m_language = "none";
    m_stats = FrameStats{};
    m_initialized = false;
}

bool FrameComposer::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k{};
    bool found = false;
#if defined(FUSE_FRAME_SLANG)
    if (m_desc.language == FrameKernelLanguage::Auto || m_desc.language == FrameKernelLanguage::Slang) {
        k = code(kFcFrameSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_FRAME_GLSL)
    if (!found && (m_desc.language == FrameKernelLanguage::Auto || m_desc.language == FrameKernelLanguage::Glsl)) {
        k = code(kFcFrameGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = k.bytes;
    moduleInfo.pCode = k.words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool FrameComposer::createImage(OwnedImage& o, u32 width, u32 height, const char* name) {
    TextureDesc d{};
    d.width = width;
    d.height = height;
    d.format = static_cast<GpuFormat>(kColorFormat);
    d.usage = imageUsage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc});
    d.name = name;
    if (!m_desc.allocator->createImage(d, o.image)) {
        return false;
    }
    o.storage = m_desc.bindless->registerTextureSlot(o.image, true);
    if (!o.storage.isValid()) {
        return false;
    }
    o.storageHandle = m_desc.bindless->shaderHandle(o.storage);
    o.layout = 0;
    o.queue = rg::kNoQueue;
    ++m_stats.imageRebuilds;
    return true;
}

bool FrameComposer::createBuffer(OwnedBuffer& o, u64 bytes, const char* name) {
    BufferDesc d{};
    d.size = static_cast<usize>(std::max<u64>(bytes, 256u));
    d.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    d.memoryUsage = MemoryUsage::GpuOnly;
    d.name = name;
    if (!m_desc.allocator->createBuffer(d, o.buffer) || o.buffer.deviceAddress == 0u) {
        return false;
    }
    o.queue = rg::kNoQueue;
    ++m_stats.imageRebuilds;
    return true;
}

bool FrameComposer::createTargets() {
    const u32 w = m_desc.renderWidth;
    const u32 h = m_desc.renderHeight;
    const u64 n = static_cast<u64>(w) * h;
    return createImage(m_skyImage, w, h, "frame.sky") && createImage(m_resolveImage, w, h, "frame.scene_color") &&
           createBuffer(m_background, n * 16u, "frame.background") && createBuffer(m_distance, n * 4u, "frame.distance") &&
           createBuffer(m_visibility, n * 4u, "frame.visibility");
}

void FrameComposer::destroyTargets() {
    for (OwnedImage* o : {&m_skyImage, &m_resolveImage}) {
        if (o->storage.isValid()) {
            m_desc.bindless->unregisterSlot(o->storage);
        }
        if (o->image.image != nullptr) {
            m_desc.allocator->destroyImage(o->image);
        }
        *o = OwnedImage{};
    }
    for (OwnedBuffer* o : {&m_background, &m_distance, &m_visibility}) {
        if (o->buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(o->buffer);
        }
        *o = OwnedBuffer{};
    }
}

u32 FrameComposer::sampledHandle(const Texture& texture) {
    if (texture.image == nullptr) {
        return 0u;
    }
    for (u32 i = 0; i < m_sampledCount; ++i) {
        if (m_sampled[i].image == texture.image) {
            return m_sampled[i].handle;
        }
    }
    if (m_sampledCount >= kSampledSlots) {
        return 0u;
    }
    SampledSlot& s = m_sampled[m_sampledCount];
    s.slot = m_desc.bindless->registerTextureSlot(texture, false);
    if (!s.slot.isValid()) {
        return 0u;
    }
    s.image = texture.image;
    s.handle = m_desc.bindless->shaderHandle(s.slot);
    ++m_sampledCount;
    ++m_stats.sampledBinds;
    return s.handle;
}

bool FrameComposer::setSdfScene(const compute::SdfObject* objects, u32 objectCount, const gi_gpu::DdgiSurface* surfaces,
                                u32 surfaceCount) {
    return (m_available & kStageDdgi) != 0u && m_ddgi.setSdfScene(objects, objectCount, surfaces, surfaceCount);
}

bool FrameComposer::setSplats(const gsplat::GsSplat* splats, u32 count, u32 shDegree) {
    return (m_available & kStageSplats) != 0u && m_gsplat.setSplats(splats, count, shDegree);
}

void FrameComposer::beginSceneFrame(u64 serial) {
    if ((m_available & kStageTlas) != 0u) {
        m_as.beginFrame(serial);
    }
}

bool FrameComposer::commitScene() {
    if ((m_available & kStageTlas) == 0u) {
        return true;
    }
    return m_as.commit().ok;
}

void FrameComposer::computeMatrices(const FrameDesc& desc, bool jitter) {
    const FrameCamera& c = desc.camera;
    const u32 w = m_desc.renderWidth;
    const u32 h = m_desc.renderHeight;
    const Basis b = basisOf(c.eye, c.target);
    lookAt(c.eye, b, m_view);
    perspective(c.fovY, static_cast<f32>(w) / static_cast<f32>(h), c.nearPlane, c.farPlane, true, m_proj);
    mul4(m_proj, m_view, m_viewProj);
    m_jitter[0] = m_jitter[1] = 0.f;
    if (jitter) {
        const math::Vec2 j = upscaleJitterOffset(desc.frameIndex, kJitterPhases);
        m_jitter[0] = j.x;
        m_jitter[1] = j.y;
    }
    temporal::jitter_view_proj(m_viewProj, m_jitter[0], m_jitter[1], w, h, m_drawViewProj);
    if (!m_hasPrev || desc.resetHistory) {
        std::memcpy(m_prevViewProj, m_viewProj, sizeof(m_viewProj));
        std::memcpy(m_prevDrawViewProj, m_drawViewProj, sizeof(m_drawViewProj));
        std::memcpy(m_prevView, m_view, sizeof(m_view));
    }
}

bool FrameComposer::beginFrame(const FrameDesc& desc, const FrameSettings& settings) {
    m_begun = false;
    if (!m_initialized) {
        return false;
    }
    m_frame = desc;
    m_settings = settings;
    m_recordCount = 0;
    const u64 serial = desc.serial;
    const u32 w = m_desc.renderWidth;
    const u32 h = m_desc.renderHeight;
    const bool t2 = m_desc.tier == FrameTier::T2;
    const bool hasSun = desc.sun.slot != 0xFFFFFFFFu && desc.sun.slot < m_desc.scene->lightHighWater();

    // --- plan -------------------------------------------------------------------------------------------------
    u32 plan = kStageScene | kStageLighting | kStageResolve;
    if (t2) {
        plan |= kStageTlas;
    }
    if (settings.vsm && hasSun) {
        plan |= kStageVsm;
    }
    if (t2 && settings.rtShadows && hasSun) {
        plan |= kStageRtShadows;
        if (settings.denoise) {
            plan |= kStageDenoise;
        }
    }
    if (settings.ddgi) {
        plan |= kStageDdgi;
    }
    if (settings.ssfx) {
        plan |= kStageSsfx;
    }
    if (settings.sky || settings.aerialPerspective) {
        plan |= kStageSky | kStageAtmosphere;
    }
    if (settings.fog) {
        plan |= kStageFog;
    }
    if (settings.clouds) {
        plan |= kStageClouds | kStageAtmosphere;
    }
    if (settings.splats && m_gsplat.splatCount() > 0u) {
        plan |= kStageSplats;
    }
    if (settings.upscaler == FrameUpscaler::Taau) {
        plan |= kStageTaau;
    } else if (settings.upscaler == FrameUpscaler::Fsr3) {
        plan |= kStageFsr3;
    }
    if (settings.post) {
        plan |= kStagePost;
    }
    // A stage that is not available is dropped (its consumers take the previous image).
    plan &= m_available | kStageScene | kStageLighting | kStageResolve;
    if ((plan & kStageDenoise) != 0u && (plan & kStageRtShadows) == 0u) {
        plan &= ~static_cast<u32>(kStageDenoise);
    }
    const bool upscale = (plan & (kStageTaau | kStageFsr3)) != 0u;
    if (!upscale && (m_desc.displayWidth != w || m_desc.displayHeight != h)) {
        // No upscaler: the output stays at render resolution.
    }
    m_plan = plan;

    computeMatrices(desc, upscale);
    f32 invDraw[16];
    if (!invert(m_drawViewProj, invDraw)) {
        return false;
    }
    const FrameCamera& cam = desc.camera;
    const Basis basis = basisOf(cam.eye, cam.target);
    const f32 aspect = static_cast<f32>(w) / static_cast<f32>(h);
    const f32 tanY = std::tan(cam.fovY * 0.5f);
    const math::Vec3 toSun = normalized(desc.sun.toSun);

    ClusterCameraDesc cluster{};
    cluster.position = vec3(cam.eye);
    cluster.forward = vec3(basis.f);
    cluster.up = math::Vec3{0.f, 1.f, 0.f};
    if (std::fabs(basis.f[1]) > 0.999f) {
        cluster.up = math::Vec3{0.f, 0.f, 1.f};
    }
    cluster.nearPlane = cam.nearPlane;
    cluster.farPlane = cam.farPlane;
    cluster.screenWidth = w;
    cluster.screenHeight = h;
    cluster.fovYRadians = cam.fovY;
    cluster.reversedZ = false;

    bool ok = true;
    // --- scene path -------------------------------------------------------------------------------------------
    gpu_scene::GpuScene& scene = *m_desc.scene;
    culling::CullFrameDesc cf{};
    std::memcpy(cf.viewProj, m_drawViewProj, sizeof(cf.viewProj));
    cf.instanceCount = scene.instanceHighWater();
    cf.cameraCut = desc.resetHistory;
    ok = m_culler.beginFrame(serial, cf) && ok;
    ok = m_vb.beginFrame(serial, m_drawViewProj, scene.headerHandle(), scene.instanceHighWater()) && ok;
    material_resolve::ResolveFrameDesc rf{};
    std::memcpy(rf.viewProj, m_drawViewProj, sizeof(rf.viewProj));
    std::memcpy(rf.prevViewProj, m_prevDrawViewProj, sizeof(rf.prevViewProj));
    rf.scene = scene.headerHandle();
    rf.vis = m_vb.visStorageHandle();
    rf.sampler = m_samplerHandle;
    ok = m_resolve.beginFrame(serial, rf) && ok;
    temporal::MotionFrameDesc mf{};
    std::memcpy(mf.viewProj, m_viewProj, sizeof(mf.viewProj));
    std::memcpy(mf.prevViewProj, m_prevViewProj, sizeof(mf.prevViewProj));
    mf.jitter_px = math::Vec2{m_jitter[0], m_jitter[1]};
    mf.scene = scene.headerHandle();
    mf.vis = m_vb.visStorageHandle();
    ok = m_motion.beginFrame(serial, mf) && ok;

    // --- shadows ----------------------------------------------------------------------------------------------
    if ((plan & kStageVsm) != 0u) {
        vsm::VsmFrameDesc vf{};
        vf.view.lightDirection[0] = -toSun.x;
        vf.view.lightDirection[1] = -toSun.y;
        vf.view.lightDirection[2] = -toSun.z;
        std::memcpy(vf.view.cameraPosition, cam.eye, sizeof(vf.view.cameraPosition));
        std::memcpy(vf.view.invViewProj, invDraw, sizeof(vf.view.invViewProj));
        vf.view.depthWidth = w;
        vf.view.depthHeight = h;
        vf.view.pixelSpread = 2.f * tanY / static_cast<f32>(h);
        vf.view.invalidateAll = desc.resetHistory;
        vf.depthHandle = m_vb.depthSampledHandle();
        vf.scene = scene.headerHandle();
        vf.instanceCount = scene.instanceHighWater();
        ok = m_vsm.beginFrame(serial, vf) && ok;
        vsm::VsmShadowFrameDesc sf{};
        sf.vsm = &m_vsm;
        sf.directionalSlot = desc.sun.slot;
        sf.scene = scene.headerHandle();
        sf.instanceCount = scene.instanceHighWater();
        sf.filter = settings.vsmFilter;
        ok = m_vsmShadows.beginFrame(serial, sf) && ok;
    }
    if ((plan & kStageRtShadows) != 0u) {
        rt_effects::RtEffectsFrameDesc rd{};
        std::memcpy(rd.viewProj, m_drawViewProj, sizeof(rd.viewProj));
        std::memcpy(rd.cameraPosition, cam.eye, sizeof(rd.cameraPosition));
        rd.scene = scene.headerHandle();
        rd.gbuffer = &m_resolve;
        rd.tlasAddress = m_as.tlasAddress();
        rd.shadowLights[0] = rt_effects::RtShadowLightDesc{desc.sun.slot, scene.light(desc.sun.slot), 1u};
        rd.shadowLightCount = 1;
        rd.reflectionSamples = 0; // WP-6.2 Open (3): no reflection consumer in the lit image yet
        rd.frameIndex = desc.frameIndex;
        std::memcpy(rd.ambient, settings.ambient, sizeof(rd.ambient));
        rd.farDistance = cam.farPlane;
        ok = m_rtfx.beginFrame(serial, rd) && ok;
        if ((plan & kStageDenoise) != 0u) {
            denoise::SvgfSettings ds = settings.denoiser;
            ds.signal = denoise::DenoiseSignal::Shadow;
            ds.gradients = false; // A-SVGF needs producer gradients (WP-6.4 Open (1))
            m_svgf.setSettings(ds);
            denoise::DenoiseFrameDesc dd{};
            dd.width = w;
            dd.height = h;
            dd.signal = m_rtfx.outputBuffer().deviceAddress + m_rtfx.outputLayout().visibility;
            dd.motion = m_motion.motionAddress();
            dd.depth = m_motion.depthAddress();
            dd.normalImage = &m_resolve.gbufferImage(0);
            dd.reset = desc.resetHistory;
            ok = m_svgf.beginFrame(serial, dd) && ok;
            rt_effects::RtfxShadowView view{};
            view.visibility = m_visibility.buffer.deviceAddress;
            view.width = w;
            view.height = h;
            view.count = 1;
            view.slots[0] = desc.sun.slot;
            const u64 offset = static_cast<u64>(serial % m_desc.framesInFlight) * kViewStride;
            std::memcpy(static_cast<u8*>(m_viewRing.mapped) + offset, &view, sizeof(view));
            m_viewAddress = m_viewRing.deviceAddress + offset;
        }
    }

    // --- DDGI -------------------------------------------------------------------------------------------------
    if ((plan & kStageDdgi) != 0u) {
        gi_gpu::DdgiFrameDesc gd{};
        gd.frameIndex = desc.frameIndex;
        gd.sunDirection = toSun;
        gd.sunIrradiance = hasSun ? vec3(desc.sun.illuminance) : math::Vec3{};
        gd.skyRadiance = vec3(settings.ddgiSkyRadiance);
        if (t2) {
            gd.tlasAddress = m_as.tlasAddress();
            gd.sceneAddress = scene.headerAddress();
        }
        if (desc.resetHistory) {
            m_ddgi.reset();
        }
        ok = m_ddgi.beginFrame(serial, gd) && ok;
    }

    // --- lighting ---------------------------------------------------------------------------------------------
    lighting_gpu::LightingFrameDesc lf{};
    lf.camera = cluster;
    lf.scene = scene.headerHandle();
    lf.lightCount = scene.lightHighWater();
    std::memcpy(lf.ambient, settings.ambient, sizeof(lf.ambient));
    lf.gbuffer = &m_resolve;
    lf.shadows = (plan & kStageVsm) != 0u ? m_vsmShadows.shadowConstantsAddress() : 0u;
    if ((plan & kStageRtShadows) != 0u) {
        lf.rtShadows = (plan & kStageDenoise) != 0u ? m_viewAddress : m_rtfx.shadowViewAddress();
    }
    lf.ddgi = (plan & kStageDdgi) != 0u ? m_ddgi.volumeAddress() : 0u;
    ok = m_lighting.beginFrame(serial, lf) && ok;

    // --- HDR chain --------------------------------------------------------------------------------------------
    const Texture* chain = &m_lighting.outputImage();
    const Texture& depth = m_resolve.gbufferImage(4);
    if ((plan & kStageSsfx) != 0u) {
        ssfx_gpu::SsfxCameraDesc sc{};
        std::memcpy(sc.view, m_view, sizeof(sc.view));
        perspective(cam.fovY, aspect, cam.nearPlane, cam.farPlane, false, sc.proj);
        sc.nearPlane = cam.nearPlane;
        sc.farPlane = cam.farPlane;
        sc.reversedZ = false;
        ssfx_gpu::SsfxFrameImages si{};
        si.normalAo = &m_resolve.gbufferImage(0);
        si.albedo = &m_resolve.gbufferImage(1);
        si.roughMetal = &m_resolve.gbufferImage(2);
        si.depth = &depth;
        si.lit = chain;
        ok = m_ssfx.beginFrame(serial, settings.ssfxSettings, sc, settings.ambient, si) && ok;
        chain = &m_ssfx.outputImage();
    }
    if ((plan & kStageAtmosphere) != 0u) {
        atmosphere::AtmosphereLutView av{};
        av.cameraPosition = vec3(cam.eye);
        av.cameraPosition.y = std::max(av.cameraPosition.y, 0.5f);
        av.sunDirection = toSun;
        av.sunIlluminance = vec3(desc.sun.illuminance);
        av.forward = vec3(basis.f);
        av.right = vec3(basis.s);
        av.up = vec3(basis.u);
        av.tanHalfFovX = tanY * aspect;
        av.tanHalfFovY = tanY;
        ok = m_atmosphere.beginFrame(serial, settings.atmosphere, av) && ok;
    }
    m_chain[0] = chain; // frame.sky input
    if ((plan & kStageSky) != 0u) {
        chain = &m_skyImage.image;
    }
    if ((plan & kStageFog) != 0u) {
        volumetric_gpu::FogFrameDesc fd{};
        fd.camera = cluster;
        fd.lighting = m_lighting.frameConstantsAddress();
        fd.shadows = (plan & kStageVsm) != 0u ? m_vsmShadows.shadowConstantsAddress() : 0u;
        fd.depth = &depth;
        fd.lit = chain;
        fd.resetHistory = desc.resetHistory;
        ok = m_fog.beginFrame(serial, settings.fogSettings, fd) && ok;
        chain = &m_fog.outputImage();
    }
    m_chain[1] = chain; // frame.gather / frame.resolve input
    if ((plan & kStageClouds) != 0u) {
        clouds::CloudSettings cs = settings.cloudSettings;
        cs.resolution.outWidth = w;
        cs.resolution.outHeight = h;
        clouds::CloudFrame cfr{};
        cfr.camera.position = vec3(cam.eye);
        cfr.camera.forward = vec3(basis.f);
        cfr.camera.right = vec3(basis.s);
        cfr.camera.up = vec3(basis.u);
        cfr.camera.tanHalfFovX = tanY * aspect;
        cfr.camera.tanHalfFovY = tanY;
        cfr.atmosphere = &m_atmosphere.params();
        cfr.atmosphereAddress = m_atmosphere.frameAddress();
        cfr.aerialPerspective = settings.aerialPerspective;
        cfr.sunDisk = settings.sunDisk;
        cfr.sunDirection = toSun;
        cfr.sunIlluminance = vec3(desc.sun.illuminance);
        cfr.ambient = vec3(settings.ambient);
        cfr.backgroundAddress = m_background.buffer.deviceAddress;
        cfr.depthAddress = m_distance.buffer.deviceAddress;
        if (desc.resetHistory) {
            m_clouds.resetHistory();
        }
        ok = m_clouds.beginFrame(serial, cs, cfr) && ok;
    }
    if ((plan & kStageSplats) != 0u) {
        const f32 up[3] = {0.f, 1.f, 0.f};
        const gsplat::GsCamera gc = gsplat::gs_camera_look_at(cam.eye, cam.target, up, cam.fovY, w, h, cam.nearPlane, cam.farPlane);
        ok = m_gsplat.beginFrame(serial, gc, settings.splatSettings, w, h, &depth) && ok;
    }

    // --- composer constants -----------------------------------------------------------------------------------
    FrameConstants c{};
    c.atmosphere = (plan & kStageAtmosphere) != 0u ? m_atmosphere.frameAddress() : 0u;
    c.background = m_background.buffer.deviceAddress;
    c.distance = m_distance.buffer.deviceAddress;
    c.clouds = (plan & kStageClouds) != 0u ? m_clouds.resultAddress() : 0u;
    c.splats = (plan & kStageSplats) != 0u ? m_gsplat.outputAddress() : 0u;
    c.denoised = (plan & kStageDenoise) != 0u ? m_svgf.outputAddress() : 0u;
    c.visibility = m_visibility.buffer.deviceAddress;
    c.width = w;
    c.height = h;
    c.inColor = sampledHandle(*m_chain[1]); // resolve / gather; frame.sky reads m_chain[0] (push-free: see addFrame)
    c.inDepth = sampledHandle(depth);
    c.outSky = m_skyImage.storageHandle;
    c.outResolve = m_resolveImage.storageHandle;
    c.flags = 0u;
    if (settings.sky) {
        c.flags |= kFrameFlagSky;
    }
    if (settings.aerialPerspective) {
        c.flags |= kFrameFlagAerial;
    }
    if (settings.sunDisk) {
        c.flags |= kFrameFlagSunDisk;
    }
    if ((plan & kStageClouds) != 0u) {
        c.flags |= kFrameFlagClouds;
    }
    if ((plan & kStageSplats) != 0u) {
        c.flags |= kFrameFlagSplats;
    }
    std::memcpy(c.invViewProj, invDraw, sizeof(c.invViewProj));
    c.cameraPos[0] = cam.eye[0];
    c.cameraPos[1] = cam.eye[1];
    c.cameraPos[2] = cam.eye[2];
    c.skyDistance = 1.0e30f;
    m_skyInColor = sampledHandle(*m_chain[0]);
    if (c.inColor == 0u || c.inDepth == 0u || m_skyInColor == 0u) {
        ok = false;
    }
    m_constants = c;
    // Two slots per ring entry: [0] = gather / resolve (chain[1]), [1] = sky (chain[0]).
    const u64 slot = static_cast<u64>(serial % m_desc.framesInFlight) * kFrameStride * 2u;
    FrameConstants skyC = c;
    skyC.inColor = m_skyInColor;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + slot, &c, sizeof(c));
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + slot + kFrameStride, &skyC, sizeof(skyC));
    m_frameAddress = m_frameRing.deviceAddress + slot;
    m_skyFrameAddress = m_frameAddress + kFrameStride;

    // --- upscale + post ---------------------------------------------------------------------------------------
    UpscaleResolution res{};
    res.render_width = w;
    res.render_height = h;
    res.display_width = upscale ? m_desc.displayWidth : w;
    res.display_height = upscale ? m_desc.displayHeight : h;
    UpscaleCamera ucam{};
    ucam.view = toMath(m_view);
    ucam.projection = toMath(m_proj);
    ucam.position = vec3(cam.eye);
    ucam.vertical_fov_rad = cam.fovY;
    ucam.aspect = aspect;
    ucam.near_plane = cam.nearPlane;
    ucam.far_plane = cam.farPlane;
    UpscaleCamera prevCam = ucam;
    prevCam.view = toMath(m_prevView);
    const Texture* display = &m_resolveImage.image;
    if ((plan & kStageTaau) != 0u) {
        temporal::TaauGpuFrameDesc td{};
        td.resolution = res;
        td.jitter_px = math::Vec2{m_jitter[0], m_jitter[1]};
        td.reset_history = desc.resetHistory;
        td.camera = ucam;
        td.previous_camera = prevCam;
        td.color = sampledHandle(m_resolveImage.image);
        td.depth = m_motion.depthAddress();
        td.motion = m_motion.motionAddress();
        ok = td.color != 0u && m_taau.beginFrame(serial, td) && ok;
        display = &m_taau.outputImage();
    } else if ((plan & kStageFsr3) != 0u) {
        fsr3::Fsr3GpuFrameDesc fd{};
        fd.resolution = res;
        fd.jitter_px = math::Vec2{m_jitter[0], m_jitter[1]};
        fd.frame_time_s = desc.deltaSeconds;
        fd.reset_history = desc.resetHistory;
        fd.camera = ucam;
        ok = m_fsr3.beginFrame(serial, fd) && ok;
        display = &m_fsr3.outputImage();
    }
    if ((plan & kStagePost) != 0u) {
        post_gpu::PostGpuSettings ps = settings.postSettings;
        ps.deltaSeconds = desc.deltaSeconds;
        post_gpu::PostFrameImages pi{};
        pi.hdr = display;
        ok = m_post.beginFrame(serial, ps, pi) && ok;
        display = &m_post.outputImage();
    }
    m_outputWidth = display->desc.width;
    m_outputHeight = display->desc.height;

    // history for the next frame
    std::memcpy(m_prevViewProj, m_viewProj, sizeof(m_viewProj));
    std::memcpy(m_prevDrawViewProj, m_drawViewProj, sizeof(m_drawViewProj));
    std::memcpy(m_prevView, m_view, sizeof(m_view));
    m_hasPrev = true;
    m_begun = ok;
    return ok;
}

FrameComposer::PassRecord* FrameComposer::nextRecord(u32 mode) {
    if (m_recordCount >= kMaxRecords) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->push.frame = mode == kFrameModeSky ? m_skyFrameAddress : m_frameAddress;
    r->push.mode = mode;
    r->groups[0] = groups(m_desc.renderWidth);
    r->groups[1] = groups(m_desc.renderHeight);
    ++m_stats.composerPasses;
    return r;
}

rg::TextureRef FrameComposer::importImage(rg::Graph& graph, OwnedImage& o, const char* name) {
    rg::ImportedImage i{};
    i.image = o.image.image;
    i.view = o.image.view;
    i.format = kColorFormat;
    i.width = o.image.desc.width;
    i.height = o.image.desc.height;
    i.initialLayout = o.layout;
    i.initialQueue = o.queue;
    i.layoutTracker = &o.layout;
    i.queueTracker = &o.queue;
    i.name = name;
    return graph.importImage(i);
}

rg::BufferRef FrameComposer::importBuffer(rg::Graph& graph, OwnedBuffer& o, const char* name) {
    return graph.importBuffer(rg::ImportedBuffer{o.buffer.handle, o.buffer.desc.size, o.queue, &o.queue, name});
}

FrameGraphOutputs FrameComposer::addFrame(rg::Graph& graph) {
    FrameGraphOutputs out{};
    m_stats.ran = 0;
    m_stats.composerPasses = 0;
    m_recordCount = 0;
    if (!m_initialized || !m_begun) {
        return out;
    }
    const u32 plan = m_plan;
    gpu_scene::GpuScene& scene = *m_desc.scene;
    u32 ran = 0;

    // --- scene path -------------------------------------------------------------------------------------------
    const gpu_scene::GpuSceneGraphRefs sceneRefs = scene.importInto(graph);
    out.scene = sceneRefs;
    rt::RtGraphRefs rtRefs{};
    if ((plan & kStageTlas) != 0u) {
        rtRefs = m_as.importInto(graph, sceneRefs);
        ran |= kStageTlas;
    }
    const culling::CullGraphRefs cull = m_culler.importInto(graph);
    const visbuffer::VisGraphRefs vis = m_vb.importInto(graph);
    m_vb.addCulledFrame(graph, vis, sceneRefs, scene.headerHandle(), m_culler, cull);
    const material_resolve::ResolveGraphRefs gbuffer = m_resolve.importInto(graph);
    m_resolve.addResolve(graph, gbuffer, vis.vis, sceneRefs, material_resolve::ResolvePath::Binned);
    out.gbuffer = gbuffer;
    const temporal::MotionGraphRefs motion = m_motion.importInto(graph);
    m_motion.addMotion(graph, motion, vis.vis, sceneRefs);
    out.motion = motion.motion;
    out.motionDepth = motion.depth;
    ran |= kStageScene;
    const rg::TextureRef depth = gbuffer.gbuffer[4];

    // --- shadows ----------------------------------------------------------------------------------------------
    vsm::VsmGraphRefs vsmRefs{};
    vsm::VsmShadowGraphRefs shadowRefs{};
    if ((plan & kStageVsm) != 0u) {
        vsmRefs = m_vsm.importInto(graph);
        m_vsm.addFrame(graph, vsmRefs, vis.depth, sceneRefs, true);
        shadowRefs = m_vsmShadows.importInto(graph);
        m_vsmShadows.addRaster(graph, shadowRefs, &vsmRefs, sceneRefs);
        ran |= kStageVsm;
    }
    rt_effects::RtEffectsGraphRefs fxRefs{};
    rg::BufferRef visibility{};
    if ((plan & kStageRtShadows) != 0u) {
        fxRefs = m_rtfx.importInto(graph);
        if (m_rtfx.addShadows(graph, fxRefs, rtRefs.tlas, gbuffer)) {
            ran |= kStageRtShadows;
        }
        if ((plan & kStageDenoise) != 0u) {
            const denoise::DenoiseGraphRefs dn = m_svgf.importInto(graph);
            denoise::DenoiseGraphInputs di{};
            di.signal = fxRefs.output;
            di.motion = motion.motion;
            di.depth = motion.depth;
            di.normalImage = gbuffer.gbuffer[0];
            m_svgf.addPasses(graph, dn, di);
            visibility = importBuffer(graph, m_visibility, "frame.visibility");
            out.denoised = dn.output;
            out.visibility = visibility;
            if (PassRecord* r = nextRecord(kFrameModeShadowPack)) {
                graph.addPass("frame.shadow_pack", &FrameComposer::recordDispatch, r)
                    .use(dn.output, rg::Access::StorageRead, {}, rg::kStageCompute)
                    .use(visibility, rg::Access::StorageWrite, {}, rg::kStageCompute);
            }
            ran |= kStageDenoise;
        }
    }

    // --- DDGI -------------------------------------------------------------------------------------------------
    gi_gpu::DdgiGraphRefs ddgiRefs{};
    if ((plan & kStageDdgi) != 0u) {
        ddgiRefs = m_ddgi.importInto(graph);
        const bool t2 = (plan & kStageTlas) != 0u;
        if (m_ddgi.addUpdate(graph, ddgiRefs, t2 ? &rtRefs : nullptr, t2 ? &sceneRefs : nullptr)) {
            ran |= kStageDdgi;
        }
    }

    // --- lighting ---------------------------------------------------------------------------------------------
    const lighting_gpu::LightingGraphRefs lighting = m_lighting.importInto(graph);
    m_lighting.addAssignment(graph, lighting, sceneRefs);
    if ((plan & kStageVsm) != 0u) {
        m_vsmShadows.addSamplingUse(graph, shadowRefs, &vsmRefs, rg::kStageCompute);
    }
    if ((plan & kStageRtShadows) != 0u) {
        if (visibility.valid()) {
            graph.addPass("frame.shadow_use", nullptr, nullptr)
                .use(visibility, rg::Access::StorageRead, {}, rg::kStageCompute)
                .neverCull();
        } else {
            m_rtfx.addSamplingUse(graph, fxRefs, rg::kStageCompute);
        }
    }
    if ((plan & kStageDdgi) != 0u) {
        m_ddgi.addSamplingUse(graph, ddgiRefs, rg::kStageCompute);
    }
    m_lighting.addShade(graph, lighting, sceneRefs, gbuffer);
    out.lighting = lighting;
    out.lit = lighting.output;
    ran |= kStageLighting;
    rg::TextureRef chain = lighting.output;

    // --- SSFX -------------------------------------------------------------------------------------------------
    if ((plan & kStageSsfx) != 0u) {
        const ssfx_gpu::SsfxGraphRefs sx = m_ssfx.importInto(graph);
        ssfx_gpu::SsfxGraphInputs si{};
        si.normalAo = gbuffer.gbuffer[0];
        si.albedo = gbuffer.gbuffer[1];
        si.roughMetal = gbuffer.gbuffer[2];
        si.depth = depth;
        si.lit = chain;
        m_ssfx.addPasses(graph, sx, si);
        out.ssfx = sx.output;
        chain = sx.output;
        ran |= kStageSsfx;
    }

    // --- atmosphere + sky -------------------------------------------------------------------------------------
    atmosphere::AtmosphereGraphRefs atm{};
    if ((plan & kStageAtmosphere) != 0u) {
        atm = m_atmosphere.importInto(graph);
        m_atmosphere.addPasses(graph, atm);
        ran |= kStageAtmosphere;
    }
    if ((plan & kStageSky) != 0u) {
        const rg::TextureRef sky = importImage(graph, m_skyImage, "frame.sky");
        if (PassRecord* r = nextRecord(kFrameModeSky)) {
            rg::PassBuilder pass = graph.addPass("frame.sky", &FrameComposer::recordDispatch, r);
            pass.use(chain, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(depth, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(sky, rg::Access::StorageWrite, {}, rg::kStageCompute);
            if (atm.luts.valid()) {
                pass.use(atm.luts, rg::Access::StorageRead, {}, rg::kStageCompute);
            }
        }
        out.sky = sky;
        chain = sky;
        ran |= kStageSky;
    }

    // --- fog --------------------------------------------------------------------------------------------------
    if ((plan & kStageFog) != 0u) {
        if ((plan & kStageVsm) != 0u) {
            m_vsmShadows.addSamplingUse(graph, shadowRefs, &vsmRefs, rg::kStageCompute);
        }
        const volumetric_gpu::FogGraphRefs fog = m_fog.importInto(graph);
        volumetric_gpu::FogGraphInputs fi{};
        fi.lights = lighting.lists;
        fi.scene = &sceneRefs;
        fi.depth = depth;
        fi.lit = chain;
        m_fog.addPasses(graph, fog, fi);
        out.fog = fog.output;
        chain = fog.output;
        ran |= kStageFog;
    }

    // --- clouds -----------------------------------------------------------------------------------------------
    clouds::CloudGraphRefs cloudRefs{};
    if ((plan & kStageClouds) != 0u) {
        const rg::BufferRef bg = importBuffer(graph, m_background, "frame.background");
        const rg::BufferRef dist = importBuffer(graph, m_distance, "frame.distance");
        if (PassRecord* r = nextRecord(kFrameModeGather)) {
            graph.addPass("frame.gather", &FrameComposer::recordDispatch, r)
                .use(chain, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(depth, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(bg, rg::Access::StorageWrite, {}, rg::kStageCompute)
                .use(dist, rg::Access::StorageWrite, {}, rg::kStageCompute);
        }
        out.background = bg;
        out.distance = dist;
        cloudRefs = m_clouds.importInto(graph);
        out.clouds = cloudRefs.frame;
        clouds::CloudInputs ci{};
        ci.atmosphereLuts = atm.luts;
        ci.background = bg;
        ci.depth = dist;
        m_clouds.addPasses(graph, cloudRefs, ci);
        ran |= kStageClouds;
    }

    // --- splats -----------------------------------------------------------------------------------------------
    gsplat::GsGraphRefs gs{};
    if ((plan & kStageSplats) != 0u) {
        gs = m_gsplat.importInto(graph);
        m_gsplat.addPasses(graph, gs, depth);
        out.splats = gs.image;
        ran |= kStageSplats;
    }

    // --- resolve ----------------------------------------------------------------------------------------------
    const rg::TextureRef sceneColor = importImage(graph, m_resolveImage, "frame.scene_color");
    if (PassRecord* r = nextRecord(kFrameModeResolve)) {
        rg::PassBuilder pass = graph.addPass("frame.resolve", &FrameComposer::recordDispatch, r);
        if ((plan & kStageClouds) != 0u) {
            pass.use(cloudRefs.frame, rg::Access::StorageRead, {}, rg::kStageCompute);
        } else {
            pass.use(chain, rg::Access::SampledRead, {}, rg::kStageCompute);
        }
        if ((plan & kStageSplats) != 0u) {
            pass.use(gs.image, rg::Access::StorageRead, {}, rg::kStageCompute);
        }
        pass.use(sceneColor, rg::Access::StorageWrite, {}, rg::kStageCompute);
    }
    out.sceneColor = sceneColor;
    ran |= kStageResolve;
    rg::TextureRef display = sceneColor;

    // --- upscale ----------------------------------------------------------------------------------------------
    if ((plan & kStageTaau) != 0u) {
        const temporal::TaauGraphRefs t = m_taau.importInto(graph);
        temporal::TaauGpuInputs ti{};
        ti.color = sceneColor;
        ti.depth = motion.depth;
        ti.motion = motion.motion;
        m_taau.addResolve(graph, t, ti);
        display = t.output;
        out.upscaled = t.output;
        ran |= kStageTaau;
    } else if ((plan & kStageFsr3) != 0u) {
        const fsr3::Fsr3GraphRefs f = m_fsr3.importInto(graph);
        fsr3::Fsr3GpuInputs fi{};
        fi.color = sceneColor;
        fi.depth = motion.depth;
        fi.motion = motion.motion;
        m_fsr3.addPasses(graph, f, fi);
        display = f.output;
        out.upscaled = f.output;
        ran |= kStageFsr3;
    }

    // --- post -------------------------------------------------------------------------------------------------
    if ((plan & kStagePost) != 0u) {
        const post_gpu::PostGraphRefs p = m_post.importInto(graph);
        post_gpu::PostGraphInputs pi{};
        pi.hdr = display;
        m_post.addPasses(graph, p, pi);
        display = p.output;
        ran |= kStagePost;
    }
    out.output = display;
    m_stats.ran = ran;
    return out;
}

u64 FrameComposer::cloudsResultOffset() const {
    return (m_available & kStageClouds) != 0u ? m_clouds.layout().offset[static_cast<u32>(clouds::CloudSection::Result)] : 0u;
}

u64 FrameComposer::splatOutputOffset() const {
    const u64 base = m_gsplat.imageBuffer().deviceAddress;
    return (m_available & kStageSplats) != 0u && m_gsplat.outputAddress() >= base ? m_gsplat.outputAddress() - base : 0u;
}

void FrameComposer::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const FrameComposer& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes,
                       &r.push);
    vkCmdDispatch(cmd, r.groups[0], r.groups[1], 1u);
#else
    (void)context;
    (void)user;
#endif
}

void FrameComposer::collectRetired(u64 completedSerial) {
    if (!m_initialized) {
        return;
    }
    m_culler.collectRetired(completedSerial);
    m_vb.collectRetired(completedSerial);
    m_resolve.collectRetired(completedSerial);
    if ((m_available & kStageVsm) != 0u) {
        m_vsm.collectRetired(completedSerial);
    }
    if ((m_available & kStageTlas) != 0u) {
        m_as.collectRetired(completedSerial);
    }
    if ((m_available & kStageRtShadows) != 0u) {
        m_rtfx.collectRetired(completedSerial);
    }
    if ((m_available & kStageDenoise) != 0u) {
        m_svgf.collectRetired(completedSerial);
    }
    m_lighting.collectRetired(completedSerial);
    if ((m_available & kStageSsfx) != 0u) {
        m_ssfx.collectRetired(completedSerial);
    }
    if ((m_available & kStageAtmosphere) != 0u) {
        m_atmosphere.collectRetired(completedSerial);
    }
    if ((m_available & kStageFog) != 0u) {
        m_fog.collectRetired(completedSerial);
    }
    if ((m_available & kStageClouds) != 0u) {
        m_clouds.collectRetired(completedSerial);
    }
    if ((m_available & kStageSplats) != 0u) {
        m_gsplat.collectRetired(completedSerial);
    }
    if ((m_available & kStageTaau) != 0u) {
        m_taau.collectRetired(completedSerial);
    }
    if ((m_available & kStageFsr3) != 0u) {
        m_fsr3.collectRetired(completedSerial);
    }
    if ((m_available & kStagePost) != 0u) {
        m_post.collectRetired(completedSerial);
    }
}

} // namespace fuse::renderer::frame
